```typescript
// apps/web/components/planner/PlannerView.tsx:222-228
const initialPayload = useMemo(
  () => (weekStart === initialWeekStart ? extractWeekData(initialWeekData) : null),
  [weekStart, initialWeekStart, initialWeekData],
)
const weekQuery = usePlannerGetWeek({ weekStart })
const weekData = extractWeekData(weekQuery.data) ?? initialPayload  // ← called on every render
```

`extractWeekData(weekQuery.data)` runs on every render even when `weekQuery.data` hasn't changed.

**Fix:**

```typescript
const rawWeekData = useMemo(
  () => extractWeekData(weekQuery.data),
  [weekQuery.data],
)
const weekData = rawWeekData ?? initialPayload
```

